@verbatim
<button aria-controls="feedback-dialog" aria-haspopup="dialog" aria-label="Share your feedback" class="feedback-tab" id="feedback-tab"><svg aria-hidden="true" class="icon" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" viewbox="0 0 24 24" width="24"><path d="M21 11a8 8 0 0 1-8 8H6l-4 3 1-7a8 8 0 1 1 18-4Z"></path><path d="M7 10h10M7 14h6"></path></svg><span>Feedback</span></button>
<dialog aria-describedby="feedback-intro" aria-labelledby="feedback-title" class="feedback-dialog" id="feedback-dialog"><div class="drawer-inner"><div class="drawer-top"><span class="drawer-symbol"><svg aria-hidden="true" class="icon" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" viewbox="0 0 24 24" width="24"><path d="M21 11a8 8 0 0 1-8 8H6l-4 3 1-7a8 8 0 1 1 18-4Z"></path><path d="M7 10h10M7 14h6"></path></svg></span><button aria-label="Close feedback form" class="icon-button" id="feedback-close"><svg aria-hidden="true" class="icon" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" viewbox="0 0 24 24" width="24"><path d="m6 6 12 12M6 18 18 6"></path></svg></button></div><div id="feedback-content"><p class="eyebrow">WE’RE LISTENING.</p><h2 id="feedback-title" tabindex="-1">A little feedback.<br/>A better experience.</h2><p id="feedback-intro">Tell us how we’re doing. Your thoughts help us make things better for you.</p><form id="feedback-form"><fieldset class="rating-field"><legend>How’s your website experience?</legend><div class="rating-options"><label class="rating-option"><input aria-label="1 — Very poor" name="rating" type="radio" value="1"/><span><svg aria-hidden="true" viewbox="0 0 32 32"><circle cx="16" cy="16" r="12"></circle><circle class="eye" cx="12" cy="13" r="1"></circle><circle class="eye" cx="20" cy="13" r="1"></circle><path d="M11 22q5-7 10 0"></path></svg><small>Very poor</small></span></label><label class="rating-option"><input aria-label="2 — Not great" name="rating" type="radio" value="2"/><span><svg aria-hidden="true" viewbox="0 0 32 32"><circle cx="16" cy="16" r="12"></circle><circle class="eye" cx="12" cy="13" r="1"></circle><circle class="eye" cx="20" cy="13" r="1"></circle><path d="M11 22q5-7 10 0"></path></svg><small>Not great</small></span></label><label class="rating-option"><input aria-label="3 — Okay" name="rating" type="radio" value="3"/><span><svg aria-hidden="true" viewbox="0 0 32 32"><circle cx="16" cy="16" r="12"></circle><circle class="eye" cx="12" cy="13" r="1"></circle><circle class="eye" cx="20" cy="13" r="1"></circle><path d="M11 21h10"></path></svg><small>Okay</small></span></label><label class="rating-option"><input aria-label="4 — Good" name="rating" type="radio" value="4"/><span><svg aria-hidden="true" viewbox="0 0 32 32"><circle cx="16" cy="16" r="12"></circle><circle class="eye" cx="12" cy="13" r="1"></circle><circle class="eye" cx="20" cy="13" r="1"></circle><path d="M10 19q6 8 12 0"></path></svg><small>Good</small></span></label><label class="rating-option"><input aria-label="5 — Excellent" name="rating" type="radio" value="5"/><span><svg aria-hidden="true" viewbox="0 0 32 32"><circle cx="16" cy="16" r="12"></circle><circle class="eye" cx="12" cy="13" r="1"></circle><circle class="eye" cx="20" cy="13" r="1"></circle><path d="M10 19q6 8 12 0"></path></svg><small>Excellent</small></span></label></div></fieldset><label class="field-label" for="feedback-type">What would you like to share?</label><select id="feedback-type" name="type"><option value="suggestion">A suggestion</option><option value="issue">Something isn’t working</option><option value="compliment">Something you loved</option><option value="other">Something else</option></select><div class="message-label"><label class="field-label" for="feedback-message">Your feedback <span aria-hidden="true">*</span></label><span aria-live="off" id="message-count">0 / 2000</span></div><textarea id="feedback-message" maxlength="2000" minlength="5" name="message" placeholder="What’s on your mind?" required="" rows="4"></textarea><div class="form-row"><div><label class="field-label" for="feedback-name">Your name <span>(optional)</span></label><input autocomplete="name" id="feedback-name" maxlength="100" name="name" placeholder="First name"/></div><div><label class="field-label" for="feedback-email">Email <span>(optional)</span></label><input autocomplete="email" id="feedback-email" maxlength="254" name="email" placeholder="you@example.com" type="email"/></div></div><p class="form-privacy">Please leave out policy numbers, payment details, and other sensitive information.</p><p class="form-error" hidden="" id="feedback-error" role="alert"></p><button class="button feedback-submit" type="submit"><span>Send feedback</span><svg aria-hidden="true" class="icon" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" viewbox="0 0 24 24" width="24"><path d="M5 12h14m-6-6 6 6-6 6"></path></svg></button><p class="feedback-bottom">Thanks for helping us get a little better.</p></form></div><div class="feedback-success" hidden="" id="feedback-success"><span class="success-icon"><svg aria-hidden="true" class="icon" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" viewbox="0 0 24 24" width="24"><path d="m5 12 4 4L19 6"></path></svg></span><p class="eyebrow">IT MEANS A LOT.</p><h2 id="feedback-success-title">Thank you for<br/>speaking up.</h2><p id="feedback-success-message">Your feedback has been recorded. We appreciate you helping us improve the Culbertson experience.</p><button class="button" id="feedback-done">Back to the website <svg aria-hidden="true" class="icon" fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" viewbox="0 0 24 24" width="24"><path d="M5 12h14m-6-6 6 6-6 6"></path></svg></button></div><div class="drawer-footer"><img alt="Culbertson Agency" src="/assets/culbertson-logo.svg" width="195"/><span>Always here to listen.</span></div></div></dialog>
@endverbatim
